//! Generic interleaved stream independent of generated primitive provenance.
use serde::{Serialize,Deserialize};use super::primitives::Vertex;
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]pub struct Stream{pub vertices:Vec<Vertex>,pub indices:Vec<[u32;3]>}
const _: [();48]=[();std::mem::size_of::<Vertex>()];
fn dot(a:[f64;3],b:[f64;3])->f64{a.iter().zip(b).map(|(a,b)|a*b).sum()}
fn cross(a:[f64;3],b:[f64;3])->[f64;3]{[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]}
pub fn unit(a:[f64;3])->Result<[f64;3],String>{if a.iter().any(|v|!v.is_finite()){return Err("finite vector required".into());}let s=a.iter().fold(0.0_f64,|s,v|s.max(v.abs()));if s==0.0{return Err("nonzero vector required".into());}let a=a.map(|v|v/s);let l=a[0].hypot(a[1]).hypot(a[2]);Ok(a.map(|v|v/l))}
impl Stream{
 pub fn validate(&self)->Result<(),String>{if self.vertices.is_empty()||self.vertices.len()>1_000_000||self.indices.is_empty()||self.indices.len()>1_000_000{return Err("stream1..1000000 vertices/triangles required".into());}for v in &self.vertices{if v.position.iter().chain(v.normal.iter()).chain(v.uv.iter()).chain(v.tangent.iter()).any(|v|!v.is_finite())||v.position.iter().any(|v|v.abs()>1e9){return Err("finite vertex attributes, position abs<=1e9 required".into());}let n=v.normal.map(|v|v as f64);let t=[v.tangent[0] as f64,v.tangent[1] as f64,v.tangent[2] as f64];if (dot(n,n)-1.).abs()>1e-4||(dot(t,t)-1.).abs()>1e-4||dot(n,t).abs()>1e-4||v.tangent[3].abs()!=1.{return Err("unit normal/tangent, orthogonal, w+/-1 required".into());}}for ids in &self.indices{if ids.iter().any(|i|*i as usize>=self.vertices.len()){return Err("stream index out of bounds".into());}let[a,b,c]=ids.map(|i|self.vertices[i as usize].position.map(|v|v as f64));let e=std::array::from_fn(|j|b[j]-a[j]);let f=std::array::from_fn(|j|c[j]-a[j]);let n=cross(e,f);if dot(n,n)==0.{return Err("zero-area triangle".into());}}Ok(())}
 pub fn inspect(&self)->Result<serde_json::Value,String>{self.validate()?;let mut lo=[f32::INFINITY;3];let mut hi=[f32::NEG_INFINITY;3];let mut uv_lo=[f32::INFINITY;2];let mut uv_hi=[f32::NEG_INFINITY;2];for v in &self.vertices{for j in 0..3{lo[j]=lo[j].min(v.position[j]);hi[j]=hi[j].max(v.position[j]);}for j in 0..2{uv_lo[j]=uv_lo[j].min(v.uv[j]);uv_hi[j]=uv_hi[j].max(v.uv[j]);}}Ok(serde_json::json!({"vertex_count":self.vertices.len(),"triangle_count":self.indices.len(),"stride_bytes":48,"offsets_bytes":[0,12,24,32],"bounds":[lo,hi],"uv_bounds":[uv_lo,uv_hi],"uv_wrapping":"caller_owned; imported UV may exceed0..1","normal_tangent_valid":true,"scene_transforms_applied":false}))}
}
/// Explicit per-triangle split tangent derivation. Preserves mirrored UV
/// handedness and avoids merging incompatible tangent frames. Not MikkTSpace.
pub fn arbitrary_tangent(normal:[f32;3])->Result<[f32;4],String>{let n=unit(normal.map(|v|v as f64))?;let axis=if n[0].abs()<0.8{[1.,0.,0.]}else{[0.,1.,0.]};let t=unit([n[1]*axis[2]-n[2]*axis[1],n[2]*axis[0]-n[0]*axis[2],n[0]*axis[1]-n[1]*axis[0]])?;Ok([t[0] as f32,t[1] as f32,t[2] as f32,1.])}
pub fn derive_tangents(mut stream:Stream)->Result<Stream,String>{if stream.indices.len()>333_333{return Err("split tangent derivation max333333 triangles".into());}let mut out=Stream{vertices:Vec::with_capacity(stream.indices.len()*3),indices:Vec::with_capacity(stream.indices.len())};for ids in &stream.indices{crate::guard::check();if ids.iter().any(|i|*i as usize>=stream.vertices.len()){return Err("index missing for tangent derivation".into());}let mut v=ids.map(|i|stream.vertices[i as usize]);let e1:[f64;3]=std::array::from_fn(|j|v[1].position[j] as f64-v[0].position[j] as f64);let e2:[f64;3]=std::array::from_fn(|j|v[2].position[j] as f64-v[0].position[j] as f64);let du1=v[1].uv[0] as f64-v[0].uv[0] as f64;let dv1=v[1].uv[1] as f64-v[0].uv[1] as f64;let du2=v[2].uv[0] as f64-v[0].uv[0] as f64;let dv2=v[2].uv[1] as f64-v[0].uv[1] as f64;let det=du1*dv2-du2*dv1;if !det.is_finite()||det.abs()<1e-20{return Err("degenerate UV triangle; cannot derive tangent".into());}let t: [f64;3]=std::array::from_fn(|j|(e1[j]*dv2-e2[j]*dv1)/det);let b: [f64;3]=std::array::from_fn(|j|(e2[j]*du1-e1[j]*du2)/det);for v in &mut v{let n=unit(v.normal.map(|v|v as f64))?;let tangent=unit(std::array::from_fn(|j|t[j]-n[j]*dot(n,t)))?;let sign=if dot(cross(n,tangent),b)<0.{-1.}else{1.};v.normal=n.map(|v|v as f32);v.tangent=[tangent[0] as f32,tangent[1] as f32,tangent[2] as f32,sign];}let base=out.vertices.len() as u32;out.vertices.extend(v);out.indices.push([base,base+1,base+2]);}stream.vertices.clear();out.validate()?;Ok(out)}
#[cfg(test)]mod tests{use super::*;
 fn fixture()->Stream{Stream{vertices:vec![Vertex{position:[0.,0.,0.],normal:[0.,0.,1.],uv:[0.,0.],tangent:[1.,0.,0.,1.]},Vertex{position:[1.,0.,0.],normal:[0.,0.,1.],uv:[1.,0.],tangent:[1.,0.,0.,1.]},Vertex{position:[0.,1.,0.],normal:[0.,0.,1.],uv:[0.,1.],tangent:[1.,0.,0.,1.]}],indices:vec![[0,1,2]]}}
 #[test]fn abi_stream_invariants_and_tangent_generation(){assert_eq!(std::mem::size_of::<Vertex>(),48);let a=derive_tangents(fixture()).unwrap();assert_eq!(a.vertices[0].tangent,[1.,0.,0.,1.]);a.validate().unwrap();let mut b=fixture();b.vertices[1].uv=[-1.,0.];let b=derive_tangents(b).unwrap();assert_eq!(b.vertices[0].tangent,[-1.,0.,0.,-1.]);}
 #[test]fn bad_indices_nonfinite_and_singular_uv_rejected(){let mut a=fixture();a.indices[0][2]=9;assert!(a.validate().is_err());let mut a=fixture();a.vertices[0].position[0]=f32::NAN;assert!(a.validate().is_err());let mut a=fixture();for v in &mut a.vertices{v.uv=[0.;2];}assert!(derive_tangents(a).is_err());}
 #[test]fn unit_scales_safely_and_pins_known_values(){assert_eq!(unit([1.,2.,2.]).unwrap(),[1./3.,2./3.,2./3.]);
  let v=unit([1e308,1e308,1e308]).unwrap();for x in v{assert!((x-1.0/f64::sqrt(3.0)).abs()<1e-15,"max-abs prescale avoids hypot overflow");}
  assert_eq!(unit([1e-308,0.,0.]).unwrap(),[1.,0.,0.],"tiny vector normalizes without underflow");
  assert_eq!(unit([0.,0.,0.]).unwrap_err(),"nonzero vector required");
  assert_eq!(unit([f64::NAN,0.,0.]).unwrap_err(),"finite vector required");}
 #[test]fn arbitrary_tangent_orthogonal_unit_and_axis_switch(){assert_eq!(arbitrary_tangent([0.,0.,1.]).unwrap(),[0.,1.,0.,1.]);
  assert_eq!(arbitrary_tangent([1.,0.,0.]).unwrap(),[0.,0.,1.,1.],"|nx|>=0.8 switches the reference axis");
  for n in [[0.79,0.61,0.05],[0.81,0.3,-0.5],[-0.2,0.9,0.39],[0.1,-0.2,0.97]]{let t=arbitrary_tangent(n).unwrap();let l=(t[0]*t[0]+t[1]*t[1]+t[2]*t[2]).sqrt();assert!((l-1.).abs()<1e-6&&t[3]==1.,"unit tangent, w=1");let d=(0..3).map(|j|t[j]*n[j]).sum::<f32>();assert!(d.abs()<1e-6,"orthogonal to normal");}
  assert!(arbitrary_tangent([0.,0.,0.]).is_err(),"zero normal rejected");}
}
